mod solution;

fn main() {
    let cases = [
    (r#"enqueue3 enqueue5 enqueue8 dequeue dequeue enqueue2 front"#, r#"8"#),
    (r#"enqueue1 enqueue2 dequeue front"#, r#"2"#),
    (r#"
enqueue1 enqueue2 dequeue front
"#, r#"2"#),
    (r#"  
enqueue3 enqueue5 enqueue8 dequeue dequeue enqueue2 front
  "#, r#"8"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS queue-with-stacks");
}
